sys_script_include.script:
var SOWNotifyWalkUpVisibilitySNC = Class.create();
SOWNotifyWalkUpVisibilitySNC.prototype = {
    initialize: function() {},
    INTERACTION_TABLE: "interaction",

    canShowCallsTab: function(recordSysId, table) {
        if (table === this.INTERACTION_TABLE) {
            var gr = new GlideRecordSecure(table);
            if (gr.get(recordSysId) && gr.getValue("type") === "walkup" && gr.canWrite())
                return true;
        }
        return false;
    },

    canShowSendSMS: function(recordSysId, table) {
        if (table === this.INTERACTION_TABLE) {
            var gr = new GlideRecordSecure(table);
            if (gr.get(recordSysId) && gr.getValue("type") === "walkup" && gr.canWrite())
                return true;
        }
        return false;
    },

    type: 'SOWNotifyWalkUpVisibilitySNC'
};
